-- Additive migration: existing meetings, tasks and settings are preserved.
ALTER TABLE "Meeting" ADD COLUMN "activeVersionId" TEXT, ADD COLUMN "materialKind" TEXT NOT NULL DEFAULT 'text', ADD COLUMN "processingStage" TEXT, ADD COLUMN "sourceKind" TEXT NOT NULL DEFAULT 'manual';
ALTER TABLE "MeetingChatMessage" ADD COLUMN "versionId" TEXT;
CREATE TABLE "DemoSpace" ("id" TEXT PRIMARY KEY,"browserHash" TEXT NOT NULL UNIQUE,"organizationId" TEXT NOT NULL UNIQUE,"used" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AiOperation" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"meetingId" TEXT,"kind" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AnalysisVersion" ("id" TEXT PRIMARY KEY,"meetingId" TEXT NOT NULL,"number" INTEGER NOT NULL,"result" JSONB NOT NULL,"snapshot" JSONB NOT NULL,"state" TEXT NOT NULL DEFAULT 'pending',"questions" INTEGER NOT NULL DEFAULT 0,"illustrationError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "AnalysisVersion_meetingId_number_key" ON "AnalysisVersion"("meetingId","number");
CREATE TABLE "Material" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"meetingId" TEXT,"folderId" TEXT,"name" TEXT NOT NULL,"kind" TEXT NOT NULL,"origin" TEXT NOT NULL DEFAULT 'manual',"provider" TEXT,"providerFileId" TEXT,"providerVersion" TEXT,"normalizedUrl" TEXT,"fingerprint" TEXT NOT NULL UNIQUE,"checksum" TEXT,"localPath" TEXT,"mime" TEXT,"bytes" INTEGER NOT NULL DEFAULT 0,"text" TEXT,"visual" JSONB,"selected" BOOLEAN NOT NULL DEFAULT true,"position" INTEGER NOT NULL DEFAULT 0,"status" TEXT NOT NULL DEFAULT 'queued',"error" TEXT,"available" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE INDEX "Material_organizationId_meetingId_idx" ON "Material"("organizationId","meetingId");
CREATE TABLE "ProcessingJob" ("id" TEXT PRIMARY KEY,"materialId" TEXT NOT NULL UNIQUE,"organizationId" TEXT NOT NULL,"operationId" TEXT NOT NULL UNIQUE,"stage" TEXT NOT NULL DEFAULT 'Получение файла',"status" TEXT NOT NULL DEFAULT 'queued',"payload" JSONB NOT NULL,"error" TEXT,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"leaseUntil" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ReportImage" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"meetingId" TEXT NOT NULL,"versionId" TEXT NOT NULL,"materialId" TEXT,"origin" TEXT NOT NULL,"localPath" TEXT NOT NULL,"caption" TEXT NOT NULL,"prompt" TEXT,"model" TEXT,"position" INTEGER NOT NULL DEFAULT 0,"included" BOOLEAN NOT NULL DEFAULT true,"needsReview" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CloudAccount" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"provider" TEXT NOT NULL,"label" TEXT NOT NULL,"tokens" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'connected',"expiresAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "OAuthAttempt" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"provider" TEXT NOT NULL,"verifier" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "CloudFolder" ("id" TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"ownerId" TEXT NOT NULL,"accountId" TEXT,"provider" TEXT NOT NULL,"name" TEXT NOT NULL,"url" TEXT NOT NULL,"providerFolderId" TEXT NOT NULL,"settings" JSONB NOT NULL,"schedule" JSONB NOT NULL,"registry" JSONB NOT NULL DEFAULT '{}',"status" TEXT NOT NULL DEFAULT 'active',"lastRunAt" TIMESTAMP(3),"nextRunAt" TIMESTAMP(3),"leaseUntil" TIMESTAMP(3),"error" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "SyncRun" ("id" TEXT PRIMARY KEY,"folderId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'running',"stats" JSONB NOT NULL DEFAULT '{}',"events" JSONB NOT NULL DEFAULT '[]',"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3));
